// @vitest-environment jsdom

import { act, cleanup, fireEvent, render, screen, waitFor, within } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import type { Goal } from "@/app/goals/types";
import type { GoalBudgetPreviewResponse } from "@/lib/planning";
// Synthetic fixture generated by GoalBudgetPreviewService + the existing certified mapper.
import fixture from "./goalBudgetFixture.json";
import zeroFixture from "./goalBudgetZeroFixture.json";

const preview = vi.hoisted(() => vi.fn());
const auth = vi.hoisted(() => ({ user: { id: "owner" } as { id: string } | null, token: "token" as string | null, isLoading: false }));
const errors = vi.hoisted(() => {
  class AuthError extends Error {}
  class APIRequestError extends Error { constructor(public status: number) { super("API error"); } }
  return { AuthError, APIRequestError };
});
vi.mock("@/contexts/AuthContext", () => ({ useAuth: () => auth }));
vi.mock("@/lib/planning", () => ({ previewGoalBudget: preview }));
vi.mock("@/lib/api", () => errors);
vi.mock("./PlanningCharts", () => ({ ProjectionChart: () => null, ScenarioComparisonChart: () => null }));

import { GoalBudgetCapability } from "./GoalBudgetCapability";

const goals: Goal[] = fixture.results.map((item) => ({
  id: item.goal_id, user_id: "owner", name: item.name, status: "ACTIVE", goal_type: "WEALTH_TARGET",
  // Legacy numeric amounts must never be read as Planning facts or presets.
  target_amount: 999999, current_amount: 888888, monthly_contribution: 777777,
  created_at: "2026-01-01T00:00:00", updated_at: item.goal_updated_at!,
}));
const refresh = vi.fn();
const props = { goals, loadingGoals: false, goalsError: null, onRefreshGoals: refresh };

beforeEach(() => {
  auth.user = { id: "owner" }; auth.token = "token"; auth.isLoading = false;
  preview.mockReset().mockResolvedValue(structuredClone(fixture));
  refresh.mockReset();
  vi.stubGlobal("requestAnimationFrame", (callback: FrameRequestCallback) => setTimeout(callback, 0));
});
afterEach(() => { cleanup(); document.documentElement.className = ""; });

function change(label: string | RegExp, value: string) {
  fireEvent.change(screen.getByLabelText(label), { target: { value } });
}

function fill(two = true) {
  fireEvent.click(screen.getByRole("checkbox", { name: /Reserva/ }));
  if (two) fireEvent.click(screen.getByRole("checkbox", { name: /Viagem/ }));
  change("Orçamento mensal", "100");
  change("Horizonte em meses", "2");
  change("Retorno hipotético anual (%)", "0");
  change("Data-base (opcional)", "28/10/2026");
  change("Aporte A · Reserva", "80"); change("Aporte B · Reserva", two ? "60" : "80");
  if (two) { change("Aporte A · Viagem", "40"); change("Aporte B · Viagem", "60"); }
}

function submit() { fireEvent.click(screen.getByRole("button", { name: "Comparar cenários" })); }

describe("Goal budget journey", () => {
  it("requires explicit selection and inputs without executing on field changes", async () => {
    render(<GoalBudgetCapability {...props} />);
    expect((screen.getByLabelText("Orçamento mensal") as HTMLInputElement).value).toBe("");
    submit();
    const alert = await screen.findByRole("alert");
    await waitFor(() => expect(document.activeElement).toBe(alert));
    expect(preview).not.toHaveBeenCalled();
    fill();
    expect(preview).not.toHaveBeenCalled();
    expect((screen.getByLabelText("Aporte A · Reserva") as HTMLInputElement).value).toBe("80");
  });

  it("sends the exact A/B request and renders certified values and deltas, not legacy numeric facts", async () => {
    const storageSpy = vi.spyOn(Storage.prototype, "setItem");
    render(<GoalBudgetCapability {...props} />);
    fill(); submit();
    const result = await screen.findByLabelText("Resultado da distribuição de orçamento");
    const request = preview.mock.calls[0][0];
    expect(request.goal_ids).toEqual(goals.map((goal) => goal.id));
    expect(request.monthly_budget).toBe("100.00");
    expect(request.assumptions).toMatchObject({ horizon_months: 2, expected_return_rate: "0", return_type: "NOMINAL", output_mode: "NOMINAL" });
    expect(request.assumptions).not.toHaveProperty("inflation_rate");
    expect(request.assumptions).not.toHaveProperty("target_date");
    expect(request.scenarios).toEqual([
      { scenario_id: "A", allocations: [{ goal_id: goals[0].id, scenario_monthly_contribution: "80.00" }, { goal_id: goals[1].id, scenario_monthly_contribution: "40.00" }] },
      { scenario_id: "B", allocations: [{ goal_id: goals[0].id, scenario_monthly_contribution: "60.00" }, { goal_id: goals[1].id, scenario_monthly_contribution: "60.00" }] },
    ]);
    expect(within(result).getAllByText("Excesso orçamentário")).toHaveLength(2);
    expect(within(result).getAllByText("R$ 20,00")).toHaveLength(2);
    const first = within(result).getByLabelText("Resultado de Reserva");
    expect(within(first).getByText("R$ 160,00")).toBeTruthy();
    expect(within(first).getByText("R$ 120,00")).toBeTruthy();
    expect(within(first).getAllByText("-R$ 40,00").length).toBeGreaterThan(0);
    expect(within(result).getByText(/Valores nominais/)).toBeTruthy();
    expect(within(first).getByText("Dados cadastrais e origem")).toBeTruthy();
    expect(result.textContent).not.toMatch(/999\.999|888\.888|777\.777|melhor cenário|recomendad/i);
    expect(storageSpy).not.toHaveBeenCalled();
    storageSpy.mockRestore();
  });

  it("supports one Goal and explicit zero budget/contributions without replacing them", async () => {
    preview.mockResolvedValue(zeroFixture);
    render(<GoalBudgetCapability {...props} />);
    fill(false); change("Orçamento mensal", "0"); change("Aporte A · Reserva", "0"); change("Aporte B · Reserva", "0,00"); submit();
    await waitFor(() => expect(preview).toHaveBeenCalledTimes(1));
    expect(preview.mock.calls[0][0]).toMatchObject({ monthly_budget: "0.00", goal_ids: [goals[0].id] });
    expect(preview.mock.calls[0][0].scenarios[0].allocations[0].scenario_monthly_contribution).toBe("0.00");
  });

  it("does not turn a missing allocation into zero and associates its error", async () => {
    render(<GoalBudgetCapability {...props} />);
    fill(); change("Aporte A · Reserva", ""); submit();
    const input = screen.getByLabelText("Aporte A · Reserva");
    expect(input.getAttribute("aria-invalid")).toBe("true");
    expect(document.getElementById(input.getAttribute("aria-describedby")!)?.textContent).toBe("Preencha este campo.");
    expect(preview).not.toHaveBeenCalled();
  });

  it("lets the server reject unequal totals and preserves the user's alternative", async () => {
    preview.mockRejectedValue(new errors.APIRequestError(422));
    render(<GoalBudgetCapability {...props} />);
    fill(); change("Aporte B · Reserva", "61"); submit();
    expect(await screen.findByRole("alert")).toHaveProperty("textContent", expect.stringContaining("exatamente iguais"));
    expect((screen.getByLabelText("Aporte B · Reserva") as HTMLInputElement).value).toBe("61");
    expect(preview.mock.calls[0][0].scenarios[1].allocations[0].scenario_monthly_contribution).toBe("61.00");
    expect((screen.getByRole("button", { name: "Comparar cenários" }) as HTMLButtonElement).disabled).toBe(false);
  });

  it.each([new errors.APIRequestError(500), new TypeError("offline")])("shows service or network failures without private detail", async (failure) => {
    preview.mockRejectedValue(failure);
    render(<GoalBudgetCapability {...props} />); fill(); submit();
    const alert = await screen.findByRole("alert");
    expect(alert.textContent).toMatch(/Não foi possível/);
    expect(screen.queryByLabelText("Resultado da distribuição de orçamento")).toBeNull();
  });

  it("requires a list refresh after uniform missing/foreign 404 and does not silently drop Goals", async () => {
    preview.mockRejectedValue(new errors.APIRequestError(404));
    const view = render(<GoalBudgetCapability {...props} />); fill(); submit();
    await screen.findByRole("alert");
    expect((screen.getByRole("button", { name: "Comparar cenários" }) as HTMLButtonElement).disabled).toBe(true);
    fireEvent.click(screen.getByRole("button", { name: "Atualizar metas" }));
    expect(refresh).toHaveBeenCalledTimes(1);
    view.rerender(<GoalBudgetCapability {...props} loadingGoals />);
    view.rerender(<GoalBudgetCapability {...props} goals={[goals[0]]} />);
    expect(screen.getByLabelText("Aporte A · Meta indisponível")).toBeTruthy();
    expect((screen.getByRole("button", { name: "Comparar cenários" }) as HTMLButtonElement).disabled).toBe(true);
    fireEvent.click(screen.getByRole("button", { name: "Limpar seleção" }));
    expect(screen.queryByLabelText("Aporte A · Reserva")).toBeNull();
  });

  it("renders partial unavailability and null time deltas without invented zeroes", async () => {
    const response = structuredClone(fixture) as GoalBudgetPreviewResponse;
    response.results[0] = { ...response.results[0], availability: "UNAVAILABLE", impediment_code: "CURRENT_AMOUNT_MISSING", current_amount: null, initial_wealth_fact: null, comparison: null };
    preview.mockResolvedValue(response);
    render(<GoalBudgetCapability {...props} />); fill(); submit();
    const item = await screen.findByLabelText("Resultado de Reserva");
    expect(within(item).getByText(/Dados insuficientes/)).toBeTruthy();
    expect(within(item).getAllByText("Não disponível")).toHaveLength(3);
    expect(screen.getByLabelText("Resultado de Viagem").textContent).toContain("Antecipação da meta em B: não disponível");
    expect(screen.getByLabelText("Orçamento do cenário A").textContent).toContain("R$ 120,00");
  });

  it("keeps budget summaries available when every projection lacks facts", async () => {
    const response = structuredClone(fixture) as GoalBudgetPreviewResponse;
    response.results = response.results.map((item) => ({ ...item, availability: "UNAVAILABLE", impediment_code: "CURRENT_AMOUNT_MISSING", current_amount: null, initial_wealth_fact: null, comparison: null }));
    preview.mockResolvedValue(response);
    render(<GoalBudgetCapability {...props} />); fill(); submit();
    await screen.findByLabelText("Resultado da distribuição de orçamento");
    expect(screen.getAllByText(/Dados insuficientes/)).toHaveLength(2);
    expect(screen.getByLabelText("Orçamento do cenário A").textContent).toContain("R$ 120,00");
    expect(screen.queryByLabelText("Diferenças de Reserva")).toBeNull();
  });

  it("uses the returned unallocated budget without summing or inferring it", async () => {
    const response = structuredClone(fixture);
    response.monthly_budget = "200";
    response.scenarios.forEach((scenario) => { scenario.unallocated_amount = "80"; scenario.exceeded_amount = "0"; });
    preview.mockResolvedValue(response);
    render(<GoalBudgetCapability {...props} />); fill(); change("Orçamento mensal", "200"); submit();
    const summary = await screen.findByLabelText("Orçamento do cenário B");
    expect(within(summary).getByText("R$ 80,00")).toBeTruthy();
    expect(within(summary).queryByText("Excesso orçamentário")).toBeNull();
  });

  it("removes a previous result immediately after any premise edit", async () => {
    render(<GoalBudgetCapability {...props} />); fill(); submit();
    await screen.findByLabelText("Resultado da distribuição de orçamento");
    change("Horizonte em meses", "3");
    expect(screen.queryByLabelText("Resultado da distribuição de orçamento")).toBeNull();
    expect(screen.getByText("Premissas ou metas alteradas. Compare novamente.")).toBeTruthy();
    expect(preview).toHaveBeenCalledTimes(1);
  });

  it("ignores a late response after editing and aborts its request", async () => {
    let resolve!: (value: unknown) => void;
    preview.mockReturnValue(new Promise((done) => { resolve = done; }));
    render(<GoalBudgetCapability {...props} />); fill(); submit();
    expect(await screen.findByText("Comparando…")).toBeTruthy();
    const signal = preview.mock.calls[0][1] as AbortSignal;
    change("Aporte A · Reserva", "70");
    expect(signal.aborted).toBe(true);
    await act(async () => resolve(fixture));
    expect(screen.queryByLabelText("Resultado da distribuição de orçamento")).toBeNull();
  });

  it.each(["logout", "identity", "token", "auth-loading"])("clears private state and ignores pending results on %s", async (changeType) => {
    let resolve!: (value: unknown) => void;
    preview.mockReturnValue(new Promise((done) => { resolve = done; }));
    const view = render(<GoalBudgetCapability {...props} />); fill(); submit();
    const signal = preview.mock.calls[0][1] as AbortSignal;
    if (changeType === "logout") { auth.user = null; auth.token = null; }
    if (changeType === "identity") { auth.user = { id: "other" }; auth.token = "new-token"; }
    if (changeType === "token") auth.token = "new-token";
    if (changeType === "auth-loading") auth.isLoading = true;
    view.rerender(<GoalBudgetCapability {...props} />);
    expect(signal.aborted).toBe(true);
    await act(async () => resolve(fixture));
    expect(screen.queryByLabelText("Resultado da distribuição de orçamento")).toBeNull();
    if (changeType === "token" || changeType === "identity") {
      expect((screen.getByLabelText("Orçamento mensal") as HTMLInputElement).value).toBe("");
      expect(screen.queryByLabelText("Aporte A · Reserva")).toBeNull();
    }
    if (changeType === "identity") expect(screen.queryByRole("checkbox", { name: /Reserva/ })).toBeNull();
  });

  it("clears financial inputs on 401 and locks execution until a new session", async () => {
    preview.mockRejectedValue(new errors.AuthError());
    render(<GoalBudgetCapability {...props} />); fill(); submit();
    expect(await screen.findByRole("alert")).toHaveProperty("textContent", expect.stringContaining("sessão expirou"));
    expect((screen.getByLabelText("Orçamento mensal") as HTMLInputElement).value).toBe("");
    expect((screen.getByRole("button", { name: "Comparar cenários" }) as HTMLButtonElement).disabled).toBe(true);
  });

  it("clears an existing budget when the authenticated Goal list reports 401", async () => {
    const view = render(<GoalBudgetCapability {...props} />); fill(); submit();
    await screen.findByLabelText("Resultado da distribuição de orçamento");
    view.rerender(<GoalBudgetCapability {...props} sessionExpired />);
    expect(screen.queryByLabelText("Resultado da distribuição de orçamento")).toBeNull();
    expect(screen.queryByLabelText("Orçamento mensal")).toBeNull();
    expect(screen.getByText(/Sua sessão expirou. Entre novamente para distribuir/)).toBeTruthy();
  });

  it.each(["logout", "identity", "token"])("removes an already rendered result immediately on %s", async (changeType) => {
    const view = render(<GoalBudgetCapability {...props} />); fill(); submit();
    await screen.findByLabelText("Resultado da distribuição de orçamento");
    if (changeType === "logout") { auth.user = null; auth.token = null; }
    if (changeType === "identity") { auth.user = { id: "other" }; auth.token = "new-token"; }
    if (changeType === "token") auth.token = "new-token";
    view.rerender(<GoalBudgetCapability {...props} />);
    expect(screen.queryByLabelText("Resultado da distribuição de orçamento")).toBeNull();
  });

  it("aborts pending work on unmount", async () => {
    let resolve!: (value: unknown) => void;
    preview.mockReturnValue(new Promise((done) => { resolve = done; }));
    const view = render(<GoalBudgetCapability {...props} />); fill(); submit();
    const signal = preview.mock.calls[0][1] as AbortSignal;
    view.unmount(); expect(signal.aborted).toBe(true);
    await act(async () => resolve(fixture));
    expect(screen.queryByLabelText("Resultado da distribuição de orçamento")).toBeNull();
  });

  it("shows list loading/failure/empty states without executable stale selection", () => {
    const view = render(<GoalBudgetCapability {...props} loadingGoals />);
    expect(screen.getByText("Carregando metas…")).toBeTruthy();
    view.rerender(<GoalBudgetCapability {...props} goalsError="failure" />);
    expect(screen.getByRole("alert").textContent).toContain("carregar as metas");
    view.rerender(<GoalBudgetCapability {...props} goals={[]} />);
    expect(screen.getByText(/Nenhuma meta disponível/)).toBeTruthy();
  });

  it("bounds selection at 20, filters foreign Goals and prevents duplicates", () => {
    const collection = Array.from({ length: 21 }, (_, index) => ({ ...goals[0], id: `00000000-0000-0000-0000-${String(index + 1).padStart(12, "0")}`, name: `Meta ${index + 1}` }));
    render(<GoalBudgetCapability {...props} goals={[...collection, collection[0], { ...goals[1], user_id: "other", name: "Privada" }]} />);
    const boxes = screen.getAllByRole("checkbox") as HTMLInputElement[];
    expect(boxes).toHaveLength(21);
    boxes.slice(0, 20).forEach((box) => fireEvent.click(box));
    expect(boxes[20].disabled).toBe(true);
    expect(screen.queryByText("Privada")).toBeNull();
    fireEvent.click(boxes[0]); expect(boxes[20].disabled).toBe(false);
  });

  it.each(["light", "dark", "system"])("keeps semantic controls and stacked mobile / paired desktop layout under %s", async (theme) => {
    document.documentElement.className = theme === "system" ? "" : theme;
    render(<GoalBudgetCapability {...props} />); fill();
    const checkbox = screen.getByRole("checkbox", { name: /Reserva/ });
    checkbox.focus(); expect(document.activeElement).toBe(checkbox);
    expect(checkbox.className).toContain("focus-visible:ring-2");
    expect(screen.getByLabelText("Orçamento mensal").className).toContain("bg-background");
    submit();
    const article = await screen.findByLabelText("Resultado de Reserva");
    const a = within(article).getByLabelText("Reserva, cenário A");
    expect(a.parentElement?.className).toContain("sm:grid-cols-2");
    expect(article.className).toContain("min-w-0");
    expect(article.querySelector("table")).toBeNull();
  });
});
